        'updates'=>['Project updates','منصوبوں کی خبریں','[awsw_updates_directory]'],
        'gallery'=>['Approved gallery','منظور شدہ تصاویر','[awsw_gallery]'],
        'faq'=>['Helpful answers','مددگار جوابات','[awsw_faq]'],
