function awsw_create_pages() {
    $ids=[];foreach(awsw_starter_pages() as $slug=>$data){$p=get_page_by_path($slug);if($p){$ids[$slug]=$p->ID;continue;}$content='<!-- wp:shortcode -->'.$data[2].'<!-- /wp:shortcode -->';$ur_content=$content;if($slug==='home'){$content=awsw_home_blocks(false);$ur_content=awsw_home_blocks(true);}elseif(in_array($slug,['about','privacy','donation-policy','terms'],true)){$_GET['lang']='en';$content=do_shortcode($data[2]);$_GET['lang']='ur';$ur_content=do_shortcode($data[2]);unset($_GET['lang']);}if(isset(awsw_programs()[$slug])){$_GET['lang']='en';$content='<!-- wp:html -->'.do_shortcode('[awsw_program program="'.$slug.'" part="intro"]').'<!-- /wp:html --><!-- wp:shortcode -->[awsw_program program="'.$slug.'" part="dynamic"]<!-- /wp:shortcode -->';$_GET['lang']='ur';$ur_content='<!-- wp:html -->'.do_shortcode('[awsw_program program="'.$slug.'" part="intro"]').'<!-- /wp:html --><!-- wp:shortcode -->[awsw_program program="'.$slug.'" part="dynamic"]<!-- /wp:shortcode -->';}$_GET['lang']='en';$content=awsw_editable_static_sections($content);$_GET['lang']='ur';$ur_content=awsw_editable_static_sections($ur_content);unset($_GET['lang']);if($slug==='about'){$content.='<!-- wp:shortcode -->[awsw_story_links]<!-- /wp:shortcode -->';$ur_content.='<!-- wp:shortcode -->[awsw_story_links]<!-- /wp:shortcode -->';}$id=wp_insert_post(['post_type'=>'page','post_status'=>$data[3]??'publish','post_name'=>$slug,'post_title'=>$data[0],'post_content'=>$content]);if($id&&!is_wp_error($id)){$ids[$slug]=$id;update_post_meta($id,'_awsw_ur_title',$data[1]);update_post_meta($id,'_awsw_ur_content',$ur_content);}}
    if(!get_option('page_on_front')&&isset($ids['home'])){update_option('show_on_front','page');update_option('page_on_front',$ids['home']);}
    update_option('timezone_string','Asia/Karachi');flush_rewrite_rules();return $ids;
}
add_action('admin_post_awsw_pages',function(){awsw_admin_guard('awsw_manage_settings');check_admin_referer('awsw_pages');awsw_create_pages();wp_safe_redirect(admin_url('admin.php?page=awsw-settings&awsw_saved=1'));exit;});
add_shortcode('awsw_programs',function(){ $html='<div class="awsw-program-grid">';foreach(awsw_programs() as $slug=>$p){$html.='<article class="awsw-program"><span aria-hidden="true">'.esc_html($p[4]).'</span><h3>'.esc_html(awsw_t($p[0],$p[1])).'</h3><p>'.esc_html(awsw_t($p[2],$p[3])).'</p>'.awsw_button(awsw_t('Explore program','مزید جانیں'),awsw_url($slug.'/'),'awsw-outline').'</article>';}return $html.'</div>';});
add_shortcode('awsw_program',function($attrs){$a=shortcode_atts(['program'=>'food'],$attrs);$s=sanitize_key($a['program']);$p=awsw_programs()[$s]??null;if(!$p){return '';}$html='<p class="awsw-lead">'.esc_html(awsw_t($p[2],$p[3])).'</p><h2>'.esc_html(awsw_t('Our approach','ہمارا طریقۂ کار')).'</h2><p>'.esc_html(awsw_t('We assess needs with the community, identify practical support, and document delivery through approved project updates. The scope, budget and use of funds are published for each campaign before donations are invited.','ہم برادری کے ساتھ ضروریات کا جائزہ لیتے، عملی معاونت طے کرتے اور منظور شدہ خبروں کے ذریعے کام کی پیش رفت بیان کرتے ہیں۔ ہر مہم کا دائرۂ کار، بجٹ اور رقم کا استعمال عطیات کی درخواست سے پہلے شائع کیا جاتا ہے۔')).'</p><h2>'.esc_html(awsw_t('Related campaigns','متعلقہ مہمات')).'</h2>'.awsw_campaign_cards(['tax_query'=>[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$s]]]).'<h2>'.esc_html(awsw_t('Project updates','منصوبوں کی خبریں')).'</h2>'.awsw_updates(['tax_query'=>[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$s]]]);return $html.awsw_button(awsw_t('Support this work','اس کام میں تعاون کریں'),awsw_url('donate/'));});
add_shortcode('awsw_about',function(){return '<p class="awsw-lead">'.esc_html(awsw_t('AWS Welfare brings people together around the essentials of a dignified life: food, education, clean water and medical care.','AWS ویلفیئر لوگوں کو باوقار زندگی کی بنیادی ضروریات—خوراک، تعلیم، صاف پانی اور علاج—کے لیے یکجا کرتا ہے۔')).'</p>'.awsw_blocks(awsw_t('Our mission','ہمارا مشن'),awsw_t('Make essential support more accessible through compassionate, accountable community action.','ہمدردانہ اور جواب دہ اجتماعی کوششوں سے ضروری معاونت تک رسائی آسان بنانا۔')).awsw_blocks(awsw_t('Our vision','ہمارا وژن'),awsw_t('Communities where people can meet essential needs and move forward with dignity.','ایسی برادریاں جہاں لوگ بنیادی ضروریات پوری کر سکیں اور عزت کے ساتھ آگے بڑھیں۔')).awsw_blocks(awsw_t('Our story','ہماری کہانی'),awsw_t('The organization’s approved founding story and dates are awaiting publication. We will add the verified history here after review.','ادارے کی منظور شدہ ابتدائی کہانی اور تاریخیں ابھی شائع ہونا باقی ہیں۔ جائزے کے بعد تصدیق شدہ تاریخ یہاں شامل کی جائے گی۔')).awsw_blocks(awsw_t('How we work','ہم کیسے کام کرتے ہیں'),awsw_t('Listen to communities. Define the need and budget. Verify contributions. Share dated updates and reviewed reports.','برادری کی بات سننا، ضرورت اور بجٹ طے کرنا، عطیات کی تصدیق کرنا، اور تاریخ وار خبریں اور جائزہ شدہ رپورٹس شائع کرنا۔')).awsw_blocks(awsw_t('Our values','ہماری اقدار'),awsw_t('Dignity, compassion, accountability and care guide how we communicate and deliver support.','عزت، ہمدردی، جواب دہی اور خیال ہماری گفتگو اور معاونت کی بنیاد ہیں۔')).'<h2>'.esc_html(awsw_t('Team & governance','ٹیم اور انتظام')).'</h2><p>'.esc_html(awsw_setting('team')?:awsw_t('Approved team and governance details are awaiting publication.','منظور شدہ ٹیم اور انتظامی معلومات ابھی شائع ہونا باقی ہیں۔')).'</p><h2>'.esc_html(awsw_t('Registration information','رجسٹریشن کی معلومات')).'</h2><p>'.esc_html(awsw_setting('registration')?:awsw_t('Verified registration information has not yet been supplied. No registration or tax status is claimed.','تصدیق شدہ رجسٹریشن معلومات ابھی فراہم نہیں کی گئیں۔ رجسٹریشن یا ٹیکس حیثیت کا کوئی دعویٰ نہیں کیا جا رہا۔')).'</p>';});
add_shortcode('awsw_transparency',function(){return '<p class="awsw-lead">'.esc_html(awsw_t('Trust grows through clear records and honest reporting.','اعتماد واضح ریکارڈ اور دیانت دارانہ رپورٹنگ سے بڑھتا ہے۔')).'</p><p>'.esc_html(awsw_t('Public fundraising totals include only staff-confirmed donations and exclude refunded records. A submitted form or screenshot is not confirmation. Delivery milestones are reported separately.','عوامی عطیات کی رقم میں صرف عملے کے تصدیق شدہ عطیات شامل ہیں؛ واپس کیے گئے عطیات شامل نہیں۔ فارم یا اسکرین شاٹ تصدیق نہیں ہے۔ عملی مراحل الگ رپورٹ کیے جاتے ہیں۔')).'</p><p>'.esc_html(awsw_t('Reports include reporting dates and explanations. Reviewed income and use-of-funds summaries, registration documents and approved PDFs will be published here when supplied. No financial results are invented.','رپورٹس میں مدت اور وضاحت شامل ہوتی ہے۔ جائزہ شدہ آمدن و اخراجات، رجسٹریشن دستاویزات اور منظور شدہ PDF فراہم ہونے پر یہاں شائع ہوں گے۔ کوئی مالی نتیجہ فرض نہیں کیا جاتا۔')).'</p>';});
add_shortcode('awsw_contact_details',function(){ $html='<div class="awsw-contact-details">';foreach(['org_email'=>['Email','ای میل'],'org_phone'=>['Phone','فون'],'address'=>['Address','پتا']] as $key=>$label){$v=awsw_setting($key);if($v){$html.='<p><strong>'.esc_html(awsw_t(...$label)).':</strong> <bdi>'.esc_html($v).'</bdi></p>';}}if(awsw_setting('whatsapp')){$html.='<a href="'.esc_url('https://wa.me/'.awsw_setting('whatsapp')).'">'.esc_html(awsw_t('Message our official WhatsApp','ہمارے سرکاری واٹس ایپ پر پیغام بھیجیں')).'</a>';}if(!awsw_setting('address')){$html.='<p class="awsw-small">'.esc_html(awsw_t('A confirmed office address and map are not yet available. Please use the enquiry form.','دفتر کا تصدیق شدہ پتا اور نقشہ ابھی دستیاب نہیں۔ براہ کرم رابطہ فارم استعمال کریں۔')).'</p>';}return $html.'</div>';});
add_shortcode('awsw_volunteer_intro',fn()=>'<p class="awsw-lead">'.esc_html(awsw_t('Share your time and skills. Tell us how you would like to help with food, education, water or medical support. The team will review your interest and availability.','اپنا وقت اور مہارت بانٹیں۔ بتائیں کہ آپ خوراک، تعلیم، پانی یا طبی معاونت میں کیسے مدد کرنا چاہیں گے۔ ٹیم آپ کی دلچسپی اور دستیابی کا جائزہ لے گی۔')).'</p>');
add_shortcode('awsw_cancelled',fn()=>awsw_empty('No online gateway is enabled. This site currently supports manual bank transfers only. A cancelled browser session does not confirm or reverse a transfer.','کوئی آن لائن گیٹ وے فعال نہیں۔ فی الحال صرف بینک ٹرانسفر دستیاب ہے۔ براؤزر سیشن بند ہونے سے ٹرانسفر کی تصدیق یا واپسی نہیں ہوتی۔'));
add_shortcode('awsw_policy',function($attrs){$a=shortcode_atts(['type'=>'privacy'],$attrs);$type=$a['type'];$html='';if(awsw_setting('policies_reviewed')!=='1'){$html.='<p class="awsw-notice">'.esc_html(awsw_t('DRAFT FOR ORGANIZATION REVIEW — this starter policy has not been approved. Confirm legal wording, contacts and retention periods before publication.','ادارے کے جائزے کا مسودہ — یہ ابتدائی پالیسی منظور شدہ نہیں۔ اشاعت سے پہلے قانونی متن، رابطوں اور ریکارڈ رکھنے کی مدت کی تصدیق کریں۔')).'</p>';}
if($type==='privacy'){$sections=[['Information we collect','جمع کی جانے والی معلومات','We collect the details you submit in donation, volunteer and contact forms to process your request. Transfer proofs are private and available only to authorized donation staff. Marketing consent is optional and separate.','عطیات، رضاکار اور رابطہ فارم کی معلومات درخواست پر کارروائی کے لیے جمع کی جاتی ہیں۔ ٹرانسفر ثبوت نجی ہیں اور صرف مجاز عملہ دیکھ سکتا ہے۔ تشہیری رضامندی الگ اور اختیاری ہے۔'],['Access, retention and your requests','رسائی، مدت اور آپ کی درخواستیں','Ask the society to access or correct your data using the contact form. Verified erasure requests can anonymize contact details and remove proofs, while financial history may be retained under the organization’s reviewed retention rules. The organization must specify its retention periods and service providers before launch.','اپنی معلومات تک رسائی یا تصحیح کے لیے رابطہ فارم استعمال کریں۔ تصدیق شدہ حذف کی درخواست پر رابطہ معلومات اور ثبوت ہٹائے جا سکتے ہیں؛ مالی تاریخ ادارے کی جائزہ شدہ پالیسی کے مطابق رکھی جا سکتی ہے۔ اجرا سے پہلے ریکارڈ رکھنے کی مدت اور خدمات فراہم کرنے والوں کی وضاحت ضروری ہے۔']];}
elseif($type==='donation'){$sections=[['Bank-transfer verification','بینک ٹرانسفر کی تصدیق','Donations are denominated in PKR. Transfers are completed outside this website through your bank. A submission stays pending until staff match the reference and amount to the bank statement. Only confirmed, non-refunded amounts contribute to public totals. No automated recurring payment is offered.','عطیات پاکستانی روپے میں ہیں۔ ٹرانسفر اپنی بینک سروس کے ذریعے کیا جاتا ہے۔ حوالہ اور رقم بینک اسٹیٹمنٹ سے ملانے تک درخواست زیرِ تصدیق رہتی ہے۔ عوامی رقم میں صرف تصدیق شدہ غیر واپس کردہ عطیات شامل ہیں۔ خودکار بار بار ادائیگی دستیاب نہیں۔'],['Corrections and refunds','تصحیح اور رقم کی واپسی','Contact the society with your submission reference to request a correction or refund review. Refund eligibility, handling periods, banking charges and approval authority must be agreed by the organization before launch. A recorded refund reflects a completed bank refund; the website itself cannot transfer funds. Acknowledgments are not tax receipts.','تصحیح یا واپسی کے جائزے کے لیے درخواست کے حوالے کے ساتھ رابطہ کریں۔ اہلیت، مدت، بینک چارجز اور مجاز منظوری ادارہ اجرا سے پہلے طے کرے گا۔ درج شدہ واپسی مکمل بینک واپسی کی نشاندہی کرتی ہے؛ ویب سائٹ خود رقم منتقل نہیں کرتی۔ تصدیقی پیغام ٹیکس رسید نہیں ہے۔']];}
else{$sections=[['Using this website','ویب سائٹ کا استعمال','Use the site and forms lawfully and provide accurate information. Published campaign information is updated by authorized staff; no promise of tax deductibility, registration status or guaranteed project outcome is made without evidence.','ویب سائٹ اور فارم جائز مقاصد کے لیے استعمال کریں اور درست معلومات دیں۔ مجاز عملہ مہمات کی معلومات تازہ کرتا ہے۔ ثبوت کے بغیر ٹیکس کٹوتی، رجسٹریشن یا یقینی نتائج کا وعدہ نہیں کیا جاتا۔'],['Questions and changes','سوالات اور تبدیلیاں','The organization must review these terms, identify the responsible contact, specify applicable terms and publish a review date before launch. Use the contact form for questions.','ادارہ اجرا سے پہلے ان شرائط کا جائزہ لے، ذمہ دار رابطہ اور قابلِ اطلاق شرائط طے کرے اور جائزے کی تاریخ شائع کرے۔ سوالات کے لیے رابطہ فارم استعمال کریں۔']];}
foreach($sections as $s){$html.=awsw_blocks(awsw_t($s[0],$s[1]),awsw_t($s[2],$s[3]));}return $html;});
add_shortcode('awsw_home',function(){return do_shortcode(do_blocks(awsw_home_blocks(awsw_lang()==='ur')));});
